// Test record factories. Each helper inserts one valid row with parameterized SQL and returns it.
// Defaults satisfy every column constraint in server/migrations; `overrides` replaces any of
// them. Unique columns (admin email, project slug, technology name) get a per-file counter, so
// repeated calls do not collide. Identity `id` columns are generated by the Database and cannot
// be overridden.
//
// `db` is any object with `query(text, params)`: the shared test db or a transaction client.

/** Plain-text password matching TEST_ADMIN_PASSWORD_HASH. */
export const TEST_ADMIN_PASSWORD = 'test-admin-password';

/**
 * bcrypt hash of TEST_ADMIN_PASSWORD at cost 4, precomputed so factories never hash.
 * Cost 4 keeps login tests fast; the production hasher uses cost 12.
 */
export const TEST_ADMIN_PASSWORD_HASH = '$2b$04$iXVLdcDtmw34Iqx3dDaBceEvF8LyapSxHUnhMOx1lGkQovvyl8lgu';

let counter = 0;
const next = () => {
  counter += 1;
  return counter;
};

const quoteIdent = (name) => `"${String(name).replace(/"/g, '""')}"`;

/**
 * Inserts `{ ...defaults, ...overrides }` into `table`. Override keys must be in `columns`,
 * which keeps column names out of reach of arbitrary input and catches typos in tests.
 * `casts` adds a type cast to a placeholder, such as `jsonb`.
 */
async function insert(db, table, columns, defaults, overrides = {}, casts = {}) {
  const unknown = Object.keys(overrides).filter((k) => !columns.includes(k));
  if (unknown.length > 0) throw new Error(`${table} factory: unknown column(s) ${unknown.join(', ')}`);

  const values = { ...defaults, ...overrides };
  const names = Object.keys(values);
  const placeholders = names.map((n, i) => `$${i + 1}${casts[n] ? `::${casts[n]}` : ''}`);
  const { rows } = await db.query(
    `INSERT INTO ${quoteIdent(table)} (${names.map(quoteIdent).join(', ')})
     VALUES (${placeholders.join(', ')}) RETURNING *`,
    names.map((n) => values[n]),
  );
  return rows[0];
}

export function createAdmin(db, overrides = {}) {
  const n = next();
  return insert(
    db,
    'admins',
    ['email', 'password_hash', 'role', 'created_at', 'updated_at'],
    { email: `admin${n}@example.com`, password_hash: TEST_ADMIN_PASSWORD_HASH, role: 'admin' },
    overrides,
  );
}

/** Inserts the single profile row (id 1). */
export function createProfile(db, overrides = {}) {
  return insert(
    db,
    'profile',
    [
      'name',
      'professional_title',
      'personal_introduction',
      'biography',
      'career_interests',
      'professional_goals',
      'profile_image_url',
      'email',
      'github_url',
      'linkedin_url',
      'created_at',
      'updated_at',
    ],
    { id: 1, name: 'Test Developer', professional_title: 'Software Engineer', email: 'owner@example.com' },
    overrides,
  );
}

