/**
 * Inserts one setting. `value` is any JSON value and is stored as JSONB.
 * The key must be one of site_title, hero_introduction, footer_text, social_links.
 */
export function createSetting(db, key = 'site_title', value = 'Test Portfolio') {
  return insert(
    db,
    'settings',
    [],
    { setting_key: key, setting_value: JSON.stringify(value) },
    {},
    { setting_value: 'jsonb' },
  );
}
